mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM child_parent cp
    INNER JOIN member m
        ON m.member_id = cp.member_id
    WHERE cp.child_id = #{childId}
      AND cp.member_id = #{memberId}
      AND m.status = 'ACTIVE'
)

SELECT

FROM time_capsule
WHERE child_id = #{childId}

    AND status = #{status}


    AND (
        created_at < #{cursorAt}
        OR (
            created_at = #{cursorAt}
            AND time_capsule_id < #{cursorId}
        )
    )

ORDER BY created_at DESC, time_capsule_id DESC
LIMIT #{limit}

SELECT

FROM time_capsule
WHERE child_id = #{childId}
  AND expected_release_at >= #{calendarStart}
  AND expected_release_at < #{calendarEnd}

    AND status = #{status}


    AND (
        expected_release_at > #{cursorAt}
        OR (
            expected_release_at = #{cursorAt}
            AND time_capsule_id > #{cursorId}
        )
    )

ORDER BY expected_release_at ASC, time_capsule_id ASC
LIMIT #{limit}
